// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        uint64 _number = 1;
        uint64 _timestamp = 1;
        uint256 _basefee = 1;
        bytes32 _hash = bytes32(uint256(1));
        uint64 _sequenceNumber = 1;
        bytes32 _batcherHash = bytes32(uint256(2));
        uint256 _l1FeeOverhead = 1;
        uint256 _l1FeeScalar = 1;

        vm.deal(caller, 1 ether);

        bool ok;
        vm.prank(caller);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == c.depositorAccount()));
    }
}
